/**
 * Kinematics -- Straight-Line Motion simulation.
 *
 * v = v0 + a*t
 * x = x0 + v0*t + (1/2)*a*t^2
 *
 * Always computed here, in code -- never fetched from a server and never
 * generated by AI. Mirrors apps/physics/simulations_kinematics.py exactly
 * (same bounds, same formulas), the same way newtons-second-law.js mirrors
 * apps/physics/simulations.py. This file owns its own physics, SVG and
 * controls; it shares only the run-loop/registry shell in lab.js.
 */
(function (window, document) {
  "use strict";

  var MIN_X0_M = -20.0;
  var MAX_X0_M = 20.0;
  var MIN_V0_MS = -20.0;
  var MAX_V0_MS = 20.0;
  var MIN_ACCEL_MS2 = -10.0;
  var MAX_ACCEL_MS2 = 10.0;
  var MAX_TIME_S = 20.0;

  function clampX0(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_X0_M, Math.min(MAX_X0_M, n));
  }

  function clampV0(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_V0_MS, Math.min(MAX_V0_MS, n));
  }

  function clampAccel(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_ACCEL_MS2, Math.min(MAX_ACCEL_MS2, n));
  }

  function computeState(x0, v0, a, t) {
    // Clamp every input the same way kinematics_state() does on the server,
    // so this exported function is safe to call standalone (e.g. from a
    // future caller or a test) and can never silently diverge from the
    // authoritative Python model.
    x0 = clampX0(x0);
    v0 = clampV0(v0);
    a = clampAccel(a);
    t = Math.max(0, Math.min(MAX_TIME_S, Number(t)));
    return {
      velocity: v0 + a * t,
      position: x0 + v0 * t + 0.5 * a * t * t
    };
  }

  // Geometry constants for the SVG scene/graph.
  var TRACK_CENTER_PX = 320;
  var PX_PER_M = 9;
  var MAX_TRACK_M = 28; // stop the run if the object would leave the visible track
  var REDUCED_MOTION_STOP_S = 6;

  function readNum(el, name, fallback) {
    var raw = el.getAttribute("data-" + name);
    var value = parseFloat(raw);
    return isFinite(value) ? value : fallback;
  }

  function round4(n) {
    return Math.round(n * 10000) / 10000;
  }

  function createKinematicsSim(root, config, lab) {
    var state = {
      x0: clampX0(readNum(root, "x0", 0)),
      v0: clampV0(readNum(root, "v0", 2)),
      accel: clampAccel(readNum(root, "accel", 1)),
      timeS: 0,
      velocityMs: 0,
      positionM: 0
    };

    var trace = []; // [t, v] pairs for the graph
    var maxAbsV = 1;

    var el = {
      scene: root.querySelector("[data-lab-scene]"),
      sceneDesc: root.querySelector("[data-scene-desc]"),
      cart: root.querySelector("[data-cart]"),
      sceneStatus: root.querySelector("[data-scene-status]"),
      graph: root.querySelector("[data-lab-graph]"),
      graphDesc: root.querySelector("[data-graph-desc]"),
      trace: root.querySelector("[data-lab-trace]"),
      valueX0: root.querySelector("[data-value-x0]"),
      valueV0: root.querySelector("[data-value-v0]"),
      valueAccel: root.querySelector("[data-value-accel]"),
      valueTime: root.querySelector("[data-value-time]"),
      valueVelocity: root.querySelector("[data-value-velocity]"),
      valuePosition: root.querySelector("[data-value-position]"),
      eqPosition: root.querySelector("[data-eq-position]"),
      eqVelocity: root.querySelector("[data-eq-velocity]"),
      outX0: root.querySelector("[data-out-x0]"),
      outV0: root.querySelector("[data-out-v0]"),
      outAccel: root.querySelector("[data-out-accel]"),
      inputX0: root.querySelector("[data-input-x0]"),
      inputV0: root.querySelector("[data-input-v0]"),
      inputAccel: root.querySelector("[data-input-accel]"),
      btnStart: root.querySelector("[data-action-start]"),
      btnPause: root.querySelector("[data-action-pause]"),
      btnReset: root.querySelector("[data-action-reset]"),
      motionNote: root.querySelector("[data-motion-note]")
    };

    var loop = lab.createRunLoop(tick, {});

    function recordTrace() {
      trace.push([round4(state.timeS), round4(state.velocityMs)]);
      maxAbsV = Math.max(maxAbsV, Math.abs(state.velocityMs));
    }

    function setX0(value) {
      state.x0 = clampX0(value);
      if (el.inputX0) el.inputX0.value = String(state.x0);
      if (el.outX0) el.outX0.textContent = String(state.x0);
      render();
    }

    function setV0(value) {
      state.v0 = clampV0(value);
      if (el.inputV0) el.inputV0.value = String(state.v0);
      if (el.outV0) el.outV0.textContent = String(state.v0);
      render();
    }

    function setAccel(value) {
      state.accel = clampAccel(value);
      if (el.inputAccel) el.inputAccel.value = String(state.accel);
      if (el.outAccel) el.outAccel.textContent = String(state.accel);
      render();
    }

    function start() {
      loop.start();
    }

    function pause() {
      loop.stop();
    }

    function reset() {
      loop.stop();
      state.timeS = 0;
      state.velocityMs = state.v0;
      state.positionM = state.x0;
      trace = [];
      maxAbsV = Math.max(1, Math.abs(state.v0));
      recordTrace();
      if (el.sceneStatus) el.sceneStatus.textContent = "";
      render();
    }

    function tick(dt) {
      if (state.timeS >= MAX_TIME_S) {
        loop.stop();
        return;
      }
      var nextT = Math.min(MAX_TIME_S, state.timeS + dt);
      var computed = computeState(state.x0, state.v0, state.accel, nextT);
      state.timeS = nextT;
      state.velocityMs = computed.velocity;
      state.positionM = computed.position;
      recordTrace();

      if (Math.abs(state.positionM) >= MAX_TRACK_M) {
        loop.stop();
        if (el.sceneStatus) el.sceneStatus.textContent = "The object left the visible track.";
      } else if (state.timeS >= MAX_TIME_S) {
        loop.stop();
        if (el.sceneStatus) {
          el.sceneStatus.textContent = "Reached the end of the simulated time window (20 s).";
        }
      } else if (loop.reduced && state.timeS >= REDUCED_MOTION_STOP_S) {
        loop.stop();
      }
      render();
    }

    function renderScene() {
      if (el.cart) {
        var x = TRACK_CENTER_PX + state.positionM * PX_PER_M;
        el.cart.setAttribute("transform", "translate(" + x.toFixed(1) + ",120)");
      }
      var text =
        "An object on a straight track at position " +
        state.positionM.toFixed(1) +
        " meters, moving at " +
        state.velocityMs.toFixed(1) +
        " meters per second.";
      if (el.scene) el.scene.setAttribute("aria-label", text);
      if (el.sceneDesc) el.sceneDesc.textContent = text;
    }

    function renderGraph() {
      if (!el.trace) return;
      var w = 348,
        h = 156,
        left = 40,
        top = 10,
        bottom = 6;
      var tMax = Math.max(1, state.timeS);
      var vMax = Math.max(1, maxAbsV);
      var points = [];
      for (var i = 0; i < trace.length; i++) {
        var t = trace[i][0],
          v = trace[i][1];
        var px = left + (t / tMax) * (w - left - 12);
        var py = h - bottom - ((v + vMax) / (2 * vMax)) * (h - top - bottom);
        points.push(px.toFixed(1) + "," + py.toFixed(1));
      }
      el.trace.setAttribute("points", points.join(" "));
      var graphText =
        "Velocity vs time. At " +
        state.timeS.toFixed(1) +
        " seconds the velocity is " +
        state.velocityMs.toFixed(1) +
        " meters per second.";
      if (el.graph) el.graph.setAttribute("aria-label", graphText);
      if (el.graphDesc) el.graphDesc.textContent = graphText;
    }

    function render() {
      if (el.valueX0) el.valueX0.textContent = String(state.x0);
      if (el.valueV0) el.valueV0.textContent = String(state.v0);
      if (el.valueAccel) el.valueAccel.textContent = state.accel.toFixed(2);
      if (el.valueTime) el.valueTime.textContent = state.timeS.toFixed(2);
      if (el.valueVelocity) el.valueVelocity.textContent = state.velocityMs.toFixed(2);
      if (el.valuePosition) el.valuePosition.textContent = state.positionM.toFixed(2);
      if (el.eqPosition) el.eqPosition.textContent = state.positionM.toFixed(2);
      if (el.eqVelocity) el.eqVelocity.textContent = state.velocityMs.toFixed(2);
      renderScene();
      renderGraph();
      root.dispatchEvent(new CustomEvent("lab:state", { detail: getState() }));
    }

    function getState() {
      return {
        initialPositionM: state.x0,
        initialVelocityMs: state.v0,
        accelerationMs2: state.accel,
        timeS: state.timeS,
        velocityMs: state.velocityMs,
        positionM: state.positionM,
        running: loop.isRunning()
      };
    }

    if (el.inputX0) {
      el.inputX0.addEventListener("input", function () {
        setX0(el.inputX0.value);
      });
      el.inputX0.addEventListener("change", function () {
        setX0(el.inputX0.value);
      });
    }
    if (el.inputV0) {
      el.inputV0.addEventListener("input", function () {
        setV0(el.inputV0.value);
      });
      el.inputV0.addEventListener("change", function () {
        setV0(el.inputV0.value);
      });
    }
    if (el.inputAccel) {
      el.inputAccel.addEventListener("input", function () {
        setAccel(el.inputAccel.value);
      });
      el.inputAccel.addEventListener("change", function () {
        setAccel(el.inputAccel.value);
      });
    }
    if (el.btnStart) el.btnStart.addEventListener("click", start);
    if (el.btnPause) el.btnPause.addEventListener("click", pause);
    if (el.btnReset) el.btnReset.addEventListener("click", reset);

    if (loop.reduced && el.motionNote) el.motionNote.hidden = false;

    reset();

    var api = {
      setX0: setX0,
      setV0: setV0,
      setAccel: setAccel,
      start: start,
      pause: pause,
      reset: reset,
      getState: getState
    };
    root.labInstance = api;
    return api;
  }

  PhysicsLab.register("kinematics", createKinematicsSim);

  // Exported for potential reuse/testing, mirroring newtons-second-law.js.
  PhysicsLab.Kinematics = {
    MIN_X0_M: MIN_X0_M,
    MAX_X0_M: MAX_X0_M,
    MIN_V0_MS: MIN_V0_MS,
    MAX_V0_MS: MAX_V0_MS,
    MIN_ACCEL_MS2: MIN_ACCEL_MS2,
    MAX_ACCEL_MS2: MAX_ACCEL_MS2,
    MAX_TIME_S: MAX_TIME_S,
    clampX0: clampX0,
    clampV0: clampV0,
    clampAccel: clampAccel,
    computeState: computeState
  };
})(window, document);
